class Solution:
    def maximumTotalValue(self, nums: List[int], s: str) -> int:
        n = len(nums)
        suf = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suf[i] = suf[i + 1] + (s[i] == '1')
        NEG = float('-inf')
        dp = [NEG] * (n + 1)
        dp[0] = 0
        for i in range(n - 1, -1, -1):
            ndp = dp[:]
            cap = suf[i]
            for c in range(1, cap + 1):
                if dp[c - 1] != NEG:
                    ndp[c] = max(ndp[c], dp[c - 1] + nums[i])
            dp = ndp
        return max(dp)

