class Solution {
public:
    long long maximumTotalValue(vector<int>& nums, string s) {
        int n = nums.size();
        vector<long long> suf(n + 1, 0);
        for (int i = n - 1; i >= 0; --i)
            suf[i] = suf[i + 1] + (s[i] == '1');
        const long long NEG = LLONG_MIN / 4;
        vector<long long> dp(n + 1, NEG), ndp(n + 1);
        dp[0] = 0;
        for (int i = n - 1; i >= 0; --i) {
            ndp = dp;
            for (long long c = 1; c <= suf[i]; ++c)
                if (dp[c - 1] > NEG / 2)
                    ndp[c] = max(ndp[c], dp[c - 1] + nums[i]);
            dp.swap(ndp);
        }
        return *max_element(dp.begin(), dp.end());
    }
};

