class Solution {
    public long maximumTotalValue(int[] nums, String s) {
        int n = nums.length;
        long[] suf = new long[n + 1];
        for (int i = n - 1; i >= 0; --i)
            suf[i] = suf[i + 1] + (s.charAt(i) == '1' ? 1 : 0);
        final long NEG = Long.MIN_VALUE / 4;
        long[] dp = new long[n + 1], ndp = new long[n + 1];
        java.util.Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int i = n - 1; i >= 0; --i) {
            System.arraycopy(dp, 0, ndp, 0, n + 1);
            for (int c = 1; c <= (int) suf[i]; ++c)
                if (dp[c - 1] > NEG / 2)
                    ndp[c] = Math.max(ndp[c], dp[c - 1] + nums[i]);
            long[] t = dp; dp = ndp; ndp = t;
        }
        long ans = 0;
        for (long v : dp) ans = Math.max(ans, v);
        return ans;
    }
}

