import heapq

class Solution:
    def maximumTotalValue(self, nums: List[int], s: str) -> int:
        n = len(nums)
        suf = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suf[i] = suf[i + 1] + (s[i] == '1')
        heap = []
        for i in range(n - 1, -1, -1):
            heapq.heappush(heap, nums[i])
            while len(heap) > suf[i]:
                heapq.heappop(heap)
        return sum(heap)

