class Solution {
public:
    long long maximumTotalValue(vector<int>& nums, string s) {
        int n = nums.size();
        vector<int> suf(n + 1, 0);
        for (int i = n - 1; i >= 0; --i)
            suf[i] = suf[i + 1] + (s[i] == '1');
        priority_queue<int, vector<int>, greater<int>> pq;
        long long ans = 0;
        for (int i = n - 1; i >= 0; --i) {
            pq.push(nums[i]);
            while ((int)pq.size() > suf[i]) pq.pop();
        }
        while (!pq.empty()) { ans += pq.top(); pq.pop(); }
        return ans;
    }
};

