        int n = nums.length;
        int[] suf = new int[n + 1];
        for (int i = n - 1; i >= 0; --i)
            suf[i] = suf[i + 1] + (s.charAt(i) == '1' ? 1 : 0);
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = n - 1; i >= 0; --i) {
            pq.offer(nums[i]);
            while (pq.size() > suf[i]) pq.poll();
        }
        long ans = 0;
        while (!pq.isEmpty()) ans += pq.poll();
        return ans;
    }
}

