var maximumTotalValue = function(nums, s) {
    const n = nums.length;
    const suf = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; --i)
        suf[i] = suf[i + 1] + (s[i] === '1' ? 1 : 0);
    const heap = [];
    const push = v => {
        heap.push(v);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0], last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < heap.length && heap[l] < heap[m]) m = l;
                if (r < heap.length && heap[r] < heap[m]) m = r;
                if (m === i) break;
                [heap[m], heap[i]] = [heap[i], heap[m]];
                i = m;
            }
        }
        return top;
    };
    for (let i = n - 1; i >= 0; --i) {
        push(nums[i]);
        while (heap.length > suf[i]) pop();
    }
    return heap.reduce((a, b) => a + b, 0);
};
